mapper.update:
update material
type_id = #{typeId}, name = #{name}, spec = #{spec}, price = #{price}, warn_threshold = #{warnThreshold}, del_flag = #{delFlag}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select *
from material
where type_id = #{typeId}
  and name = #{name}
  and del_flag = 0
